+/** Record a target-specific relation event and refresh the query's tracked membership. */
+function updatePairTracking(
+    world: World,
+    query: QueryInstance,
+    entity: Entity,
+    target: Entity,
+    eventType: EventType
+) {
+    let affected = false;
+    for (const group of query.trackingGroups) {
+        for (let index = 0; index < group.pairs.length; index++) {
+            const pair = group.pairs[index];
+            const pairCtx = pair[$internal];
+            if (pairCtx.target !== '*' && pairCtx.target !== target) continue;
+
+            // The callback is registered only for this relation, but checking identity
+            // keeps this safe if a relation trait is ever shared by a wrapper.
+            const relationTrait = pairCtx.relation[$internal].trait;
+            if (!hasTraitInstance(world[$internal].traitInstances, relationTrait)) continue;
+
+            const opposite =
+                (eventType === 'add' && (group.type === 'remove' || group.type === 'change')) ||
+                (eventType === 'remove' && (group.type === 'add' || group.type === 'change'));
+            if (group.type !== eventType && !opposite) continue;
+
+            let terms = group.pairTrackers.get(entity);
+            if (!terms) group.pairTrackers.set(entity, (terms = new Map()));
+            let targets = terms.get(index);
+            if (!targets) terms.set(index, (targets = new Set()));
+
+            if (group.type === eventType) targets.add(target);
+            else targets.delete(target);
+            affected = true;
+        }
+    }
+
+    if (!affected) return;
+    const relationTrait = query.traits.find((trait) => trait[$internal].relation)?.[$internal];
+    // Pair groups have no trait bitmask. A zero bit event lets the normal checker
+    // evaluate static and regular tracking constraints while pair state is checked below.
+    const match = query.checkTracking(world, entity, eventType, relationTrait ? 0 : 0, 0);
+    if (match) query.add(entity);
+    else query.remove(world, entity);
+}
